## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked
This problem validates DP mastery (two implementations) and handling of substring lookups with a dictionary. It stresses practical constraints and edge-case handling.

## Key Concepts
- Bottom-up DP, Memoization, Time: O(N * maxLen)
- Hash-map lookups for dictionary scores
- Edge cases: no decomposition, empty input, overlapping choices

## Code Example
```javascript
// Bottom-up
function maxScore(s, dict) {
  const maxLen = Math.max(...Object.keys(dict).map(k => k.length));
  const n = s.length;
  const NEG = -1e15;
  const dp = new Array(n + 1).fill(NEG);
  dp[0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let len = 1; len <= Math.min(i, maxLen); len++) {
      const substr = s.slice(i - len, i);
      if (dict.hasOwnProperty(substr) && dp[i - len] !== NEG) {
        dp[i] = Math.max(dp[i], dp[i - len] + dict[substr]);
      }
    }
  }
  return dp[n] === NEG ? -1 : dp[n];
}

// Top-down
function maxScoreTopDown(s, dict) {
  const maxLen = Math.max(...Object.keys(dict).map(k => k.length));
  const memo = new Map();
  function solve(i) {
    if (i === s.length) return 0;
    if (memo.has(i)) return memo.get(i);
    let best = -Infinity;
    for (let len = 1; len <= Math.min(maxLen, s.length - i); len++) {
      const substr = s.substring(i, i + len);
      if (dict.hasOwnProperty(substr)) {
        const val = dict[substr] + solve(i + len);
        if (val > best) best = val;
      }
    }
    memo.set(i, best);
    return best;
  }
  const res = solve(0);
  return res === -Infinity ? -1 : res;
}
``` 

